173	        }
174	        claim.setStatus(next);
175	        claims.flush();
176	        String person = owner == null ? "" : owner.getName();
177	        String event = switch (next) {
178	            case OPEN -> "CLAIM_OPENED";
179	            case PENDING -> "CLAIM_PENDING";
180	            case SETTLED -> "CLAIM_SETTLED";
181	            case VOID -> "CLAIM_VOIDED";
182	            case DRAFT -> throw new IllegalStateException();
183	        };
184	        events.publishEvent(new ClaimChanged(event, sheetId, user, person, claim.getAmount(), claim.getDate(), number, due));
