253	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
254	        Person to = people.findByIdAndSheetId(toPersonId, sheetId)
255	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.CONFLICT, "Choose a person on the sheet"));
256	        if (from.getId().equals(to.getId())) {
