311	                .findFirst().orElse(null);
312	        String sequence = period == null ? "X" : "P" + period.getId();
313	        int n = claims.lastInSequence(sheetId, sequence) + 1;
314	        claim.setPeriodNumber(sequence, n, (period == null ? "X" : period.getName()) + "-" + n);
