    public PersonView approve(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @PathVariable long claimId, @RequestHeader("X-User") @NotBlank String user) {
        String sheet = sheetId.trim();
        return view(sheet, claims.approve(sheet, user.trim(), claimId));
    }

    /** A steward rejects a PENDING claim with a reason, putting it back to OPEN. */
    @PostMapping("/claims/{claimId}/reject")
    public PersonView reject(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @PathVariable long claimId, @RequestHeader("X-User") @NotBlank String user,
            @Valid @RequestBody RejectForm form) {
        String sheet = sheetId.trim();
        return view(sheet, claims.reject(sheet, user.trim(), claimId, form.reason().trim()));
    }

    /** A steward moves a claim to another person; answers with the person it left and the one it joined. */
    @PostMapping("/claims/{claimId}/reassign")
    public List<PersonView> reassign(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @PathVariable long claimId, @RequestHeader("X-User") @NotBlank String user,
            @Valid @RequestBody ReassignForm form) {
        String sheet = sheetId.trim();
        long[] moved = claims.reassign(sheet, user.trim(), claimId, form.personId());
        return List.of(view(sheet, moved[0]), view(sheet, moved[1]));
    }

    @PostMapping("/claims/{claimId}/void")
    public PersonView voidClaim(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @PathVariable long claimId, @RequestHeader("X-User") @NotBlank String user) {
        return move(sheetId, claimId, user, ClaimStatus.VOID);
    }

    private PersonView move(String sheetId, long claimId, String user, ClaimStatus next) {
        String sheet = sheetId.trim();
        return view(sheet, claims.move(sheet, user.trim(), claimId, next));
    }

    private PersonView view(String sheetId, long personId) {
        return PersonView.of(people.get(sheetId, personId), claims.forPerson(sheetId, personId),
                rates.table(sheetId), statements.forPerson(sheetId, personId), people.patrons(sheetId, personId));
    }

    /** A claim dated inside a closed period: refused, nothing changed. */
    @ExceptionHandler(ClosedPeriodRefused.class)
    public ResponseEntity<Refusal> closed(ClosedPeriodRefused e) {
        return ResponseEntity.status(HttpStatus.CONFLICT).body(new Refusal(e.getMessage()));
    }

    /** Another save took a quick-added person's name first: refused, nothing changed. */
    @ExceptionHandler(DataIntegrityViolationException.class)
    @ResponseStatus(HttpStatus.CONFLICT)
    public void nameInUse() {
    }
}
package net.officefloor.hq.app.claim;

import java.util.Comparator;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import net.officefloor.hq.app.period.ClosedPeriodRefused;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import org.springframework.stereotype.Service;
import org.springframework.web.server.ResponseStatusException;

/**
 * Opens a selection of claims together, numbered in list order: the people in the order they were
 * added, each person's newest claim first. Each claim is opened on its own, so one that cannot be
 * opened is refused and left as it is while the rest go through.
 */
@Service
public class BulkOpenService {

    public record Result(int opened, int refused) {
    }

    private final ClaimService claims;
    private final ClaimRepository claimRows;
    private final PersonRepository people;

    public BulkOpenService(ClaimService claims, ClaimRepository claimRows, PersonRepository people) {
        this.claims = claims;
        this.claimRows = claimRows;
        this.people = people;
    }

    public Result open(String sheetId, String user, Set<Long> claimIds) {
        Map<Long, Integer> personOrder = new HashMap<>();
        List<Person> listed = people.findBySheetIdOrderByIdAsc(sheetId);
        for (int i = 0; i < listed.size(); i++) {
            personOrder.put(listed.get(i).getId(), i);
        }
        List<Claim> selected = claimRows.findBySheetIdOrderByListedDesc(sheetId).stream()
                .filter(c -> claimIds.contains(c.getId()))
                .sorted(Comparator.comparing((Claim c) -> personOrder.getOrDefault(c.getPersonId(), Integer.MAX_VALUE))
                        .thenComparing(Claim::getListed, Comparator.reverseOrder()))
                .toList();
        int opened = 0;
        for (Claim c : selected) {
            try {
                claims.move(sheetId, user, c.getId(), ClaimStatus.OPEN);
                opened++;
            } catch (ResponseStatusException | ClosedPeriodRefused refused) {
                // refused: left as it is
            }
        }
        return new Result(opened, claimIds.size() - opened);
    }
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.person.PersonService;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/**
 * Quick-add: a DRAFT claim of an amount, dated the sheet's today with an empty note, for the person
 * of a name, matched as the person form matches names; a name not on the sheet adds the person first
 * with grade A. The whole of it is one change: a refused claim leaves no new person behind.
 */
@Service
public class QuickAddService {

    private static final String GRADE = "A";

    private final PersonRepository people;
    private final PersonService persons;
    private final ClaimService claims;

    public QuickAddService(PersonRepository people, PersonService persons, ClaimService claims) {
        this.people = people;
        this.persons = persons;
        this.claims = claims;
    }

    /** Returns the person the claim belongs to. */
    @Transactional
    public long add(String sheetId, String user, String name, BigDecimal amount) {
        String trimmed = name.trim();
        Person person = people.findBySheetIdAndNameIgnoreCase(sheetId, trimmed)
                .orElseGet(() -> persons.add(sheetId, user, trimmed, GRADE));
        return claims.add(sheetId, user, person.getId(), amount, null, "");
    }
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.util.List;
import java.util.Objects;
import net.officefloor.hq.app.rate.Grades;
import net.officefloor.hq.app.rate.RateService;
import net.officefloor.hq.app.rate.RateTable;

/** The due figures of claims and the due-total of a person's claims. */
public final class Dues {

    private Dues() {
    }

    /**
     * A claim's due: once settled, the due fixed then (its late charge frozen in); otherwise its
     * {@link #base} figure plus, while overdue, its {@link RateTable#lateCharge late charge}. Null when there
     * is none.
     */
    public static BigDecimal figure(Claim claim, Grades grades, RateTable rates) {
        if (claim.getSettledDue() != null) {
            return claim.getSettledDue();
        }
        BigDecimal base = base(claim, grades, rates);
        if (base == null || claim.isCorrection() || !overdue(claim, rates)) {
            return base;
        }
        return base.add(rates.lateCharge(base, claim.getDueBy(), claim.getRoundsBy()));
    }

    /**
     * A claim's figure before any late charge: while bound by a statement (and not PENDING, which is
     * never bound), the figure bound then;
     * otherwise the amount at the rate in force on its date for its person's grade in force then, but at
     * least the sheet's floor; a correction has no floor and no late charge. Rounded by the date the claim's
     * rounding goes by, see {@link RateTable#rounding}. Null when there is none. A
     * statement binds this figure, never the late charge.
     */
    public static BigDecimal base(Claim claim, Grades grades, RateTable rates) {
        if (bound(claim)) {
            return claim.getStatedDue();
        }
        String grade = grades.on(claim.getDate());
        return claim.isCorrection() ? RateService.due(claim.getAmount(), rates.on(grade, claim.getDate()),
                rates.rounding(claim.getRoundsBy()))
                : rates.due(claim.getAmount(), grade, claim.getDate());
    }

    /** Whether a statement binds the claim's figure: it is stated and not PENDING. */
    public static boolean bound(Claim claim) {
        return claim.isStated() && claim.getStatus() != ClaimStatus.PENDING;
    }

    /** Whether the claim is overdue: OPEN or PENDING, and due by a date before the sheet's today (its due-by, fixed when it was added). */
    public static boolean overdue(Claim claim, RateTable rates) {
        return claim.getStatus().unpaid() && claim.getDueBy().isBefore(rates.today());
    }

    /** The overdue claims that count, see {@link #overdue} and {@link #counts}. */
    public static List<Claim> overdue(List<Claim> claims, RateTable rates, boolean held) {
        return claims.stream().filter(c -> counts(c, held) && overdue(c, rates)).toList();
    }

    /** The sum of the due figures of the claims given (0.00 with none); a claim with none is skipped. */
    public static BigDecimal sum(Grades grades, List<Claim> claims, RateTable rates) {
        return claims.stream().map(c -> figure(c, grades, rates)).filter(Objects::nonNull)
                .reduce(BigDecimal.ZERO, BigDecimal::add);
    }

    /** Whether the claim's figure is kept whatever the rates: fixed by settling or bound by a statement. */
    private static boolean kept(Claim claim) {
        return claim.getSettledDue() != null || (bound(claim) && claim.getStatedDue() != null);
    }

    /**
     * Whether the claim counts in the live totals: OPEN, PENDING and SETTLED claims do, except that the
     * OPEN and PENDING claims of a person on hold count in none.
     */
    public static boolean counts(Claim claim, boolean held) {
        return claim.getStatus().counts() && !(held && claim.getStatus().unpaid());
    }

    /**
     * The sum of the due figures of the claims that count (0.00 with none); a person not on hold.
     */
    public static BigDecimal total(Grades grades, List<Claim> claims, RateTable rates) {
        return total(grades, claims, rates, false);
    }

    /**
     * The sum of the due figures of the claims that count (0.00 with none), see {@link #counts}. Null (n/a)
     * when the grade in force on the sheet's today has no rate on it, unless a claim that counts has a
     * figure not made by that grade (kept, or at the rate for another grade in force on its date): then it
     * is the sum of the figures there are.
     */
    public static BigDecimal total(Grades grades, List<Claim> claims, RateTable rates, boolean held) {
        List<Claim> counting = claims.stream().filter(c -> counts(c, held)).toList();
        String current = grades.on(rates.today());
        boolean shown = rates.current(current) != null || counting.stream().anyMatch(c -> kept(c)
                || (!current.equals(grades.on(c.getDate())) && figure(c, grades, rates) != null));
        return shown ? counting.stream().map(c -> figure(c, grades, rates))
                .filter(Objects::nonNull).reduce(BigDecimal.ZERO, BigDecimal::add) : null;
    }
}
